import {tr} from './owner-import.js';
import {t,language,money,nameOf,switcher} from './i18n.js';
import {escapeHtml as e,savedFloorSvg} from './floor-shared.js';
import {receiptDocument,receiptSuccess,receiptSkeleton,receiptFailed,receiptActions,receiptShareText} from './receipt.js';
const $=s=>document.querySelector(s),key=()=>crypto.randomUUID(),path=location.pathname;
let data,visit=null,share=null,category='All items',search='',screen='menu',cart=JSON.parse(sessionStorage.getItem('resuto-cart-v2')||'[]'),token=sessionStorage.getItem('resuto-token'),selected=null,reservation=null,receipt=null,closed=null,busy=false,revision=-1;
const saveCart=()=>sessionStorage.setItem('resuto-cart-v2',JSON.stringify(cart));
async function api(route,body){const r=await fetch('/api/'+route,{method:body?'POST':'GET',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(t(d.error));return d;}
const button=(label,action,extra='',cls='primary')=>`<button type="button" class="${cls}" data-do="${action}" ${extra}>${t(label)}</button>`;
const input=(label,name,type='text',value='',extra='')=>`<label>${t(label)}<input name="${name}" type="${type}" value="${e(value)}" ${extra}></label>`;
const moneyRow=(label,value)=>`<div class="money-row"><span>${t(label)}</span><strong>${money(value)}</strong></div>`;
const photo=(m,cls='')=>m.imageUrl?`<div role="img" aria-label="${e(nameOf(m))}" class="dish-photo ${cls}" style="background-image:url('${e(m.imageUrl)}');background-size:cover;background-position:center"></div>`:m.imageIndex>=0?`<div role="img" aria-label="${e(nameOf(m))}" class="dish-photo ${cls}" style="background-position:${m.imageIndex%2?90:10}% ${Math.floor(m.imageIndex/2)*100/3}%"></div>`:`<div class="dish-placeholder ${cls}" aria-label="${e(nameOf(m))}">◌</div>`;
const toast=message=>{const el=$('#toast');el.textContent=t(message);el.className='show';setTimeout(()=>el.className='',5000)};
function modal(title,html){$('dialog')?.remove();document.body.insertAdjacentHTML('beforeend',`<dialog class="guest-sheet"><div class="sheet-head"><h2>${t(title)}</h2>${button('Close','dismiss','','icon')}</div>${html}</dialog>`);const dialog=$('dialog');dialog.showModal();dialog.addEventListener('close',()=>dialog.remove(),{once:true});}
const close=()=>{const dialog=$('dialog');if(dialog){dialog.close();dialog.remove();}};
const pending=(scope,payload)=>{const id='pending-v2-'+scope,old=JSON.parse(sessionStorage.getItem(id)||'null'),fp=JSON.stringify(payload);if(old?.fp===fp)return old.key;const k=key();sessionStorage.setItem(id,JSON.stringify({key:k,fp}));return k;};
function header(){return `<header class="consumer-header"><a class="olive-logo" href="/restaurant">${data.brand?.logo?`<img src="${e(data.brand.logo)}" alt="" style="max-width:70px;max-height:50px;object-fit:contain">`:''}${e(t(data.settings.name))}<small>${t('Example restaurant')}</small></a><nav><a href="/menu">${t('Menu')}</a><a href="/reserve">${t('Reservations')}</a>${switcher()}</nav></header>`;}
function shell(html){$('#app').innerHTML=`<div class="consumer-app">${header()}${html}<footer class="consumer-footer"><span>${t('Example restaurant')} · ${t('Menu illustrations')}</span><a href="/">${t('Powered by Resuto')}</a></footer></div>`;}
function cards(){const filtered=data.menu.filter(m=>(category==='All items'||m.category===category)&&(m.name+' '+m.nameAr+' '+m.description).toLowerCase().includes(search.toLowerCase()));return filtered.map(m=>`<article class="dish-card ${cartQtyOf(m.id)?'in-cart':''}" data-dish="${m.id}"><button type="button" class="photo-button" data-do="product" data-id="${m.id}" aria-label="${t('Details')}: ${e(nameOf(m))}">${photo(m)}</button><div class="dish-body"><div class="dish-tags">${m.vegetarian?'<span>'+t('Vegetarian')+'</span>':''}${m.spice?'<span>'+t('Spicy')+'</span>':''}${m.stock&&m.stock<6?'<span class="is-low">'+t('Only a few left')+'</span>':''}</div><button type="button" class="dish-name" data-do="product" data-id="${m.id}"><h3>${e(nameOf(m))}</h3></button><p>${e(language==='ar'?m.descriptionAr||m.description:m.description)}</p><div class="dish-bottom"><strong>${money(m.price)}</strong>${dishControl(m)}</div></div></article>`).join('')||`<div class="guest-empty"><h2>${t('No matching dishes')}</h2><p>${t('Try another search or category.')}</p></div>`;}
const cartTotal=()=>cart.reduce((n,l)=>n+l.qty*l.price,0),cartCount=()=>cart.reduce((n,l)=>n+l.qty,0);
// How many of this dish are in the cart, across option combinations.
const cartQtyOf=id=>cart.filter(l=>l.id===id).reduce((n,l)=>n+l.qty,0);
// The plain (no-options) line is the one +/- on the card adjusts.
const plainLine=id=>cart.find(l=>l.id===id&&!l.options?.length);
// One tap adds; after that the card becomes a stepper. Dishes with options
// still open the sheet, because a choice has to be made before pricing.
function dishControl(m){
 if(!m.available||!m.stock)return `<span class="dish-sold">${t('Sold out')}</span>`;
 const qty=cartQtyOf(m.id);
 if(m.modifiers?.length)return button(qty?`${qty} · ${t('Add')}`:t('Choose'),'product',`data-id="${m.id}"`,'dish-add');
 if(!qty)return `<button type="button" class="dish-add" data-do="quick-add" data-id="${m.id}" aria-label="${t('Add')} ${e(nameOf(m))}"><span aria-hidden="true">+</span> ${t('Add')}</button>`;
 return `<div class="dish-stepper" role="group" aria-label="${e(nameOf(m))}">
  <button type="button" data-do="qty-minus" data-id="${m.id}" aria-label="${t('Remove one')}">−</button>
  <output aria-live="polite">${qty}</output>
  <button type="button" data-do="qty-plus" data-id="${m.id}" aria-label="${t('Add one')}" ${qty>=m.stock?'disabled':''}>+</button></div>`;
}
// Update only what changed. Re-rendering the whole grid on every tap threw
// the guest back to the top of the menu, which is unusable on a phone.
function syncDish(id){
 const card=document.querySelector(`[data-dish="${CSS.escape(id)}"]`),m=data.menu.find(x=>x.id===id);
 if(card&&m){card.classList.toggle('in-cart',!!cartQtyOf(id));card.querySelector('.dish-bottom').innerHTML=`<strong>${money(m.price)}</strong>${dishControl(m)}`;}
 syncDock();
}
function syncDock(){
 const dock=$('.cart-dock');if(!dock)return;
 dock.classList.toggle('has-items',!!cartCount());
 const total=dock.querySelector('strong'),count=dock.querySelector('.cart-count');
 if(total)total.textContent=money(cartTotal());
 if(count)count.textContent=cartCount();
}
// Adds respect the kitchen's stock count; the guest is told when it runs out.
function addToCart(id,step=1){
 const m=data.menu.find(x=>x.id===id);if(!m)return;
 const line=plainLine(id),have=cartQtyOf(id);
 if(step>0&&have>=m.stock)return toast('No more portions available.');
 if(line){line.qty+=step;if(line.qty<1)cart.splice(cart.indexOf(line),1);}
 else if(step>0)cart.push({id,qty:1,price:m.price,options:[]});
 saveCart();syncDish(id);
}
// Live total on the sheet's button: base price + ticked options x quantity.
function sheetTotal(){
 const form=$('[data-guest-form="add"]'),out=$('#sheet-total');if(!form||!out)return;
 const m=data.menu.find(x=>x.id===form.dataset.id);if(!m)return;
 const picked=[...form.querySelectorAll('[name="options"]:checked')].map(x=>x.value);
 const unit=m.price+m.modifiers.filter(x=>picked.includes(x.id)).reduce((n,x)=>n+x.price,0);
 out.textContent=money(unit*Number($('#sheet-qty')?.textContent||1));
}
function menu(){shell(`<section class="menu-cover"><img src="/assets/olive-interior.png" alt="${e(t(data.settings.name))}"><div><span class="overline">${e(t(data.settings.name))}</span><h1>${t('Your favorites, at your pace.')}</h1><p>${t('Seasonal plates, warm hospitality and a place at our table.')}</p></div></section><main class="consumer-main"><div class="menu-context"><span>◉ ${e(language==='ar'?data.branches[0].nameAr:data.branches[0].name)}</span><span>${visit?.tableId?e(data.tables.find(x=>x.id===visit.tableId)?.label):t('Choose fulfillment at checkout.')}</span>${visit?button('View order','status','','secondary'):''}</div><section class="menu-assistant"><div class="ai-mark">✧</div><div><strong>${t('Find something you will love, within your budget.')}</strong><p>${t('Menu assistant')}</p></div>${button('Help me choose','assistant','','secondary')}</section><div class="menu-discovery"><label class="search-box"><span>⌕</span><input id="dish-search" type="search" placeholder="${t('Search dishes')}" value="${e(search)}" aria-label="${t('Search dishes')}"></label><nav class="dish-categories">${['All items',...new Set(data.menu.map(m=>m.category))].map(c=>button(c,'category',`data-category="${e(c)}" aria-pressed="${category===c}"`,category===c?'active':'')).join('')}</nav></div><div id="dish-grid" class="dish-grid">${cards()}</div></main><div class="cart-dock">${visit?button('View bill','bill','','secondary'):''}${button('View cart','cart',`aria-label="${t('View cart')} (${cartCount()})"`)}<strong>${money(cartTotal())}</strong><span class="cart-count">${cartCount()}</span></div>`);}
function home(){shell(`<main><section class="restaurant-editorial"><img src="/assets/olive-interior.png" alt="${e(t(data.settings.name))}"><div><span class="overline">${e(t(data.settings.name))}</span><h1>${t('Good food. Long conversations.')}</h1><p>${t('Seasonal plates, warm hospitality and a place at our table.')}</p><a class="primary button" href="/menu">${t('Browse menu')} ↗</a><a class="secondary button" href="/reserve">${t('Book a table')}</a></div></section><section class="consumer-main restaurant-introduction"><div><span class="overline">${e(t(data.settings.name))}</span><h2>${t('Dinner, without the back-and-forth.')}</h2><p>${t('Choose confidently. Order at your pace.')}</p><a href="/menu">${t('Browse menu')} ↗</a></div>${photo(data.menu[0])}</section><section class="consumer-main"><h2>${t('Menu')}</h2><div class="dish-grid">${data.menu.slice(0,3).map(m=>`<a class="dish-card" href="/menu">${photo(m)}<div class="dish-body"><h3>${e(nameOf(m))}</h3><strong>${money(m.price)}</strong></div></a>`).join('')}</div></section></main>`);}
function product(id){const m=data.menu.find(x=>x.id===id);modal(nameOf(m),`${photo(m,'product-photo')}<p>${e(language==='ar'?m.descriptionAr||m.description:m.description)}</p><p class="fine">${t('Listed allergens')}: ${e(m.allergens.map(x=>t(x[0].toUpperCase()+x.slice(1))).join('، '))||'—'}. ${t('Ask staff about allergens and cross-contact.')}</p><form data-guest-form="add" data-id="${m.id}">${m.modifiers.length?`<h3>${t('Options')}</h3>${m.modifiers.map(x=>`<label class="check"><input type="checkbox" name="options" value="${e(x.id)}" ${x.required?'required':''} ${x.available?'':'disabled'}>${e(nameOf(x))} + ${money(x.price)}</label>`).join('')}`:''}<div class="sheet-qty"><span>${t('Quantity')}</span><div class="dish-stepper is-large"><button type="button" data-do="sheet-minus" aria-label="${t('Remove one')}">−</button><output id="sheet-qty" aria-live="polite">1</output><button type="button" data-do="sheet-plus" data-max="${m.stock}" aria-label="${t('Add one')}">+</button></div><input type="hidden" name="qty" value="1"></div><button class="primary full" ${!m.available||!m.stock?'disabled':''}>${t('Add to order')} · <b id="sheet-total">${money(m.price)}</b></button></form>`);}
function cartSheet(){if(cart.length)setTimeout(fillCartSuggestions,0);modal('Your order',`${cart.map((l,i)=>{const m=data.menu.find(m=>m.id===l.id);const opts=(l.options||[]).map(id=>m.modifiers.find(x=>x.id===id)).filter(Boolean);
   return `<div class="cart-item">${photo(m)}<div class="cart-item-body"><strong>${e(nameOf(m))}</strong>${opts.length?`<small class="cart-opts">${opts.map(x=>e(nameOf(x))).join(' · ')}</small>`:''}<small class="cart-unit">${money(l.price)} ${t('each')}</small><div class="quantity-row"><div class="dish-stepper"><button type="button" data-do="cart-minus" data-index="${i}" aria-label="${t('Remove one')}">−</button><output aria-live="polite">${l.qty}</output><button type="button" data-do="cart-plus" data-index="${i}" aria-label="${t('Add one')}">+</button></div><b class="cart-line-total">${money(l.price*l.qty)}</b></div></div></div>`}).join('')||`<div class="cart-empty-state"><p>${t('Your cart is empty.')}</p>${button('Browse menu','menu','','secondary full')}</div>`}${moneyRow('Subtotal',cartTotal())}<div id="cart-suggest"></div>${button(visit?'Confirm order':'Checkout',visit?'dine-order':'checkout',`${!cart.length||visit?.locked||path.startsWith('/t/')&&!visit?'disabled':''}`,'primary full')}${path.startsWith('/t/')&&!visit?`<p>${t('Ask staff to open your table to order.')}</p>`:''}`);}
function paymentOptions(branch,billMode=false,allowRequests=true){const options=[];if(data.payments.mode!=='live'&&(!branch||['auto','demo'].includes(branch.paymentProvider)))options.push(`<option value="demo">${t('Test payment — no charge')}</option>`);for(const provider of data.payments.providers.filter(p=>!branch||['auto',p].includes(branch.paymentProvider)))options.push(`<option value="${provider}">${provider==='stripe'?'Stripe · '+t('Card'):'Paymob · '+t('Card')}</option>`);if(billMode&&data.payments.methods?.find(x=>x.id==='wallet'&&x.available))options.push(`<option value="paymob-wallet">Paymob · ${t('Wallet')}</option>`);if(billMode&&allowRequests&&data.payments.methods?.find(x=>x.id==='instapay'&&x.available))options.push(`<option value="instapay">${t('InstaPay · manual confirmation')}</option>`);if(billMode&&allowRequests)options.push(`<option value="cash">${t('Pay at restaurant · request')}</option>`);return options.join('');}
function updateCheckoutBranch(){const form=$('[data-guest-form="online"]');if(!form)return;const b=data.branches.find(x=>x.id===form.elements.branchId.value);const old=form.elements.type.value;form.elements.type.innerHTML=(b.pickup?`<option value="pickup">${t('Pickup')}</option>`:'')+(b.delivery&&data.settings.deliveryEnabled?`<option value="delivery">${t('Delivery')}</option>`:'');if([...form.elements.type.options].some(x=>x.value===old))form.elements.type.value=old;form.elements.area.innerHTML=b.deliveryAreas.map(x=>`<option>${e(x)}</option>`).join('');form.elements.payment.innerHTML=paymentOptions(b);form.elements.type.dispatchEvent(new Event('change',{bubbles:true}));}
function checkout(){modal('Checkout',`<form data-guest-form="online"><label>${t('Payment method')}<select name="payment">${paymentOptions()}</select></label><div class="form-grid">${input('First name','name','text','','required maxlength="100"')}${input('Contact','contact','tel','','required maxlength="100"')}</div><label>${t('Pickup')} / ${t('Delivery')}<select name="type"><option value="pickup">${t('Pickup')}</option>${data.settings.deliveryEnabled?`<option value="delivery">${t('Delivery')}</option>`:''}</select></label><label>${t('Branch')}<select name="branchId">${data.branches.filter(b=>b.active).map(b=>`<option value="${b.id}">${e(language==='ar'?b.nameAr||b.name:b.name)}</option>`).join('')}</select></label><div id="delivery-details" hidden><label>${t('Delivery area')}<select name="area">${data.branches[0].deliveryAreas.map(x=>`<option>${e(x)}</option>`).join('')}</select></label>${input('Address','address','text','','maxlength="500"')}</div><label>${t('Notes for the kitchen')}<textarea name="notes" maxlength="500"></textarea></label><div id="checkout-total">${moneyRow('Total',cartTotal())}</div><p class="fine">${t('Review your cart before placing the order.')}</p><button class="primary full">${t('Place order')}</button></form>`);updateCheckoutBranch();}
function assistant(){modal('Menu assistant',`<div class="guest-chat"><div id="ai-result" class="chat-thread" aria-live="polite"><div class="chat-bubble bot"><span class="chat-avatar">✧</span><p>${tr('Tell me what you feel like eating. How many people, your budget, and anything to avoid?','نفسك تاكل إيه؟ قول لي عدد الأشخاص والميزانية وأي حاجة تحب تتجنبها.')}</p></div><div class="chat-prompts">${[[tr('A meal for two under EGP 500','وجبة لشخصين بميزانية ٥٠٠ جنيه'),tr('For two','لشخصين')],[tr('Vegetarian, not spicy','نباتي ومش حار'),tr('Vegetarian','نباتي')],[tr('Something quick','حاجة سريعة'),tr('Quick meal','وجبة سريعة')]].map(([value,label])=>`<button type="button" data-chat-prompt="${e(value)}">${label}</button>`).join('')}</div></div><form data-guest-form="ai" class="chat-composer"><details class="chat-preferences"><summary>${tr('Budget & dietary preferences','الميزانية والتفضيلات الغذائية')}</summary><div class="form-grid">${input('Total budget (EGP)','budget','number',700,'min="1" required')}${input('People','party','number',2,'min="1" max="20" required')}</div><label class="check"><input type="checkbox" name="vegetarian">${t('Vegetarian only')}</label><label class="check"><input type="checkbox" name="mild">${t('Not spicy')}</label><fieldset><legend>${t('Exclude allergens')}</legend>${['milk','eggs','wheat','fish'].map(x=>`<label class="check"><input type="checkbox" name="exclude" value="${x}">${t(x[0].toUpperCase()+x.slice(1))}</label>`).join('')}</fieldset></details><label class="chat-input-label" for="ai-preferences">${tr('Your message','رسالتك')}</label><div class="chat-send-row"><textarea name="text" id="ai-preferences" maxlength="1000" rows="2" placeholder="${tr('For three, under EGP 1,000, not spicy…','إحنا ٣ وميزانيتنا ١٠٠٠، ومش عايزين حار…')}"></textarea><button class="primary" aria-label="${t('Suggest a meal')}">${tr('Send','إرسال')} ↑</button></div><small>${tr('Recommendations use the current menu. Confirm allergies with staff.','الاقتراحات من القائمة الحالية. تأكد من فريق المطعم بخصوص الحساسية.')}</small></form></div>`);document.querySelector('dialog').classList.add('chat-sheet');}
let recommendation=null;
function renderRecommendation(r){recommendation=r;const thread=$('#ai-result');thread.querySelector('[data-chat-loading]')?.remove();thread.insertAdjacentHTML('beforeend',`<div class="chat-bubble bot"><span class="chat-avatar">✧</span><div><small class="chat-mode">${t(r.mode)}</small><p>${e(r.message)}</p></div></div><div class="chat-meal-cards">${r.recommendedItems.map(x=>{const m=data.menu.find(m=>m.id===x.menuItemId);return `<article class="chat-meal-card">${photo(m)}<div><h3>${e(nameOf(m))}</h3><p>${e(x.reason)}</p><div><span>${x.quantity} × ${money(m.price)}</span><strong>${money(x.quantity*m.price)}</strong></div></div></article>`;}).join('')}</div>${r.lines.length?`<div class="chat-meal-total">${moneyRow('Estimated total',r.estimatedTotal)}${button('Add recommended meal','accept-ai','','primary full')}</div>`:''}${r.followUpQuestion?`<p class="chat-follow-up">${e(r.followUpQuestion)}</p>`:''}<p class="chat-allergy">${e(r.warnings.join(' '))}</p>`);thread.scrollTop=thread.scrollHeight;}
function timeline(o){let stages=o.type==='delivery'?['received','preparing','ready','out_for_delivery','delivered']:o.type==='pickup'?['received','preparing','ready','picked_up']:['received','preparing','ready','served'];const labels={received:'Order received',preparing:'Preparing',ready:o.type==='pickup'?'Ready for pickup':'Ready',served:'Served',picked_up:'Picked up',out_for_delivery:'Out for delivery',delivered:'Delivered'},index=stages.indexOf(o.status);return `<ol class="order-timeline">${stages.map((x,i)=>`<li class="${i<=index?'done':''}" ${i===index?'aria-current="step"':''}><i>${i<index?'✓':i+1}</i><span>${t(labels[x])}</span></li>`).join('')}</ol>`;}
function statusPage(){screen='status';shell(`<main class="consumer-main status-page"><span class="overline">${t('Order status')}</span><h1>${t('Your order is on its way.')}</h1>${visit.orders.map(o=>`<article class="status-order"><header><strong>#${o.number}</strong><span>${money(o.total)}</span></header>${o.status==='cancelled'?`<p>${t('Cancelled')}</p>`:timeline(o)}<div>${o.lines.map(l=>`<p>${l.qty} × ${e(language==='ar'?l.nameAr||l.name:l.name)}</p>`).join('')}</div></article>`).join('')}<div class="status-actions">${button('Browse menu','menu','','secondary')}${button('View bill','bill')}${visit.type==='dine-in'?button('Call waiter','waiter','','secondary'):''}</div>${receiptHistory()}</main>`);}
function billSheet(){const bill=visit.bill;modal('Split & pay',`<div id="bill-summary">${moneyRow('Total',bill.total)}${bill.credit?moneyRow('Reservation deposit',bill.credit):''}${moneyRow('Paid',bill.paid)}${moneyRow('Remaining',bill.due)}<progress max="${bill.total||1}" value="${Math.min(bill.total,bill.paid+bill.credit)}" aria-label="${t('Payment progress')}"></progress></div><div id="split-live">${splitMarkup()}</div>${!visit.split&&bill.due?`<div class="bill-choice">${button('Pay full bill','full-pay')}${button('Split bill','split-create','','secondary')}</div>`:''}${bill.due?'':`<div class="settled">✓ ${t('Your current balance is settled.')}</div>${!visit.rated?button('How was your experience?','rate','','secondary full'):''}`}${(visit.checkout||[]).filter(c=>c.url).map(c=>`<a class="secondary button" href="${e(c.url)}">${t('Resume checkout')}</a>`).join('')}`);}
function splitMarkup(){const split=visit?.split;if(!split)return '';return `<p class="fine">${t('Names are visible only to people sharing this bill.')} · ${t(split.method)}</p>${split.shares.map((x,i)=>`<div class="share-row"><span class="share-avatar">${x.status==='paid'?'✓':i+1}</span><div><strong>${e(x.name||t('Guest')+' '+(i+1))}</strong><small>${money(x.amount)} · ${t(x.status==='paid'?'Paid':'Pending')}</small></div>${x.status==='paid'?'':`<a class="text-button" href="${e(x.url)}" target="_blank">${t('Pay this share')}</a>${button('QR','qr',`data-url="${e(x.url)}"`,'icon')}${button('Copy link','copy',`data-url="${e(x.url)}"`,'icon')}${button('Share','share',`data-url="${e(x.url)}"`,'icon')}`}</div>`).join('')}`;}
function splitChooser(){modal('Split bill',`<div class="split-method-picker">${[['equal','Split equally'],['items','Split by item'],['custom','Custom amounts']].map(([method,label])=>button(label,'split-method',`data-method="${method}"`,'secondary full')).join('')}</div><p class="fine">${t('Deposits, fees, prior payments and rounding are included in the remaining balance.')}</p>`);}
function splitForm(method){const names=`<label>${t('Optional names, one per line')}<textarea name="names"></textarea></label>`,people=input('People','people','number',4,'min="2" max="20" required');if(method==='equal')return modal('Split equally',`<form data-guest-form="split"><input type="hidden" name="method" value="equal">${people}${names}<button class="primary full">${t('Create payment links')}</button></form>`);if(method==='custom')return modal('Custom amounts',`<form data-guest-form="split"><input type="hidden" name="method" value="custom"><label>${t('Amounts in EGP, one per line')}<textarea name="amounts" required placeholder="300\n300\n300\n300"></textarea></label>${names}<p class="fine">${t('Amounts must equal the remaining balance.')} ${money(visit.bill.due)}</p><button class="primary full">${t('Create payment links')}</button></form>`);
 const rows=visit.orders.filter(o=>o.status!=='cancelled').flatMap(o=>o.lines.flatMap((line,lineIndex)=>Array.from({length:line.qty},(_,unit)=>({orderId:o.id,lineIndex,unit,name:line.nameAr&&language==='ar'?line.nameAr:line.name,price:line.price}))));return modal('Split by item',`<form data-guest-form="split"><input type="hidden" name="method" value="items">${people}${names}<div class="item-allocation">${rows.map((item,index)=>`<label><span>${e(item.name)} · ${money(item.price)}</span><select name="item:${item.orderId}:${item.lineIndex}:${item.unit}">${[0,1,2,3].map(i=>`<option value="${i}" ${i===index%4?'selected':''}>${t('Share')} ${i+1}</option>`).join('')}</select></label>`).join('')}</div><p class="fine">${t('Every item must be assigned exactly once.')}</p><button class="primary full">${t('Create payment links')}</button></form>`);}
function payForm(shareMode=false){modal('Continue to payment',`<form data-guest-form="${shareMode?'share-payment':'bill-payment'}">${shareMode?input('First name','firstName','text',share.name||'','required maxlength="60"'):''}${moneyRow(shareMode?'Your share':'Remaining',shareMode?share.amount:visit.bill.due)}<label>${t('Payment method')}<select name="provider">${paymentOptions(null,true,!shareMode)}</select></label><div id="provider-details" hidden>${!shareMode?input('First name','firstName','text','','maxlength="60"'):''}${input('Last name','lastName')}${input('Email','email','email')}${input('Phone','phone','tel')}</div><p id="payment-note" class="fine"></p><button class="primary full">${t('Continue to payment')}</button></form>`);updateProvider();}
function updateProvider(){const provider=$('dialog [name="provider"]')?.value,details=$('#provider-details'),note=$('#payment-note');if(details){const needs=provider==='paymob'||provider==='paymob-wallet';details.hidden=!needs;details.querySelectorAll('input').forEach(x=>x.required=needs);}if(note)note.textContent=provider==='cash'?t('This sends a payment request to restaurant staff.'):provider==='instapay'?t('Transfer to the displayed merchant address. A manager must confirm it manually.'):provider==='demo'?t('Test mode. No real money is charged.'):t('Payment is completed on the provider checkout.');}
function sharePage(){screen='share';shell(`<main class="invitation"><div class="invitation-mark">${share.status==='paid'?'✓':'÷'}</div><span class="overline">${e(share.restaurant)}</span><h1>${t(share.status==='paid'?'Payment complete':'You are invited to share a bill.')}</h1><p>${e(share.branch||'')}</p><div class="share-amount"><span>${t('Your share')}</span><strong>${money(share.amount)}</strong></div>${share.status==='paid'?button('View receipt','share-receipt','','primary full')+button('How was your experience?','rate','','secondary full'):share.checkout?`<a class="primary button" href="${e(share.checkout)}">${t('Resume checkout')}</a>`:button('Continue to payment','share-open','','primary full')}<p>${t('Remaining')}: ${money(share.remaining)}</p></main>`);}
// ---- Counter ticket ---------------------------------------------------------
// A guest who scanned the counter QR is standing in the venue, so there is no
// pickup-or-delivery question to ask. What they need is the number to quote at
// the till and a straight choice: settle it now on the phone, or at the counter.
const isCounter=()=>visit?.type==='counter';
const counterNumber=()=>{const open=(visit?.orders||[]).filter(o=>o.status!=='cancelled');return open.length?open[open.length-1].number:null;};
function counterTicket(){
 screen='counter';
 const bill=visit.bill,number=counterNumber(),awaiting=(visit.requests||[]).some(r=>r.type==='bill'&&r.status==='open');
 shell(`<main class="consumer-main counter-page">
  <span class="overline">${e(t(data.settings.name))}</span>
  <h1>${t('Your order is in.')}</h1>
  <section class="counter-ticket">
   <span>${t('Show this number at the counter')}</span>
   <strong>#${String(number||0).padStart(3,'0')}</strong>
   <div class="counter-amount"><span>${t('Amount due')}</span><b>${money(bill.due)}</b></div>
  </section>
  ${bill.due?awaiting
   ?`<div class="counter-await"><span class="live-dot"></span>${t('The cashier has your order. Pay at the counter with this number.')}</div>`
   :`<div class="counter-choice">
      ${button('Pay now on my phone','counter-pay-now','','primary full')}
      ${button('Pay at the counter','counter-pay-cashier','','secondary full')}
     </div>`
   :`<div class="settled">✓ ${t('Paid in full. Thank you.')}</div>`}
  <div class="status-actions">${button('Add more items','menu','','secondary')}${button('View bill','bill','','secondary')}</div>
  ${visit.orders.length?`<section class="counter-orders"><h2>${t('Order status')}</h2>${visit.orders.map(o=>`<article class="status-order"><header><strong>#${String(o.number).padStart(3,'0')}</strong><span>${money(o.total)}</span></header>${o.status==='cancelled'?`<p>${t('Cancelled')}</p>`:timeline(o)}</article>`).join('')}</section>`:''}
  ${receiptHistory()}</main>`);
}

// ---- Complementary suggestions ---------------------------------------------
// Offered after an order is placed and inside the cart. Tapping one only ever
// puts it in the cart — the guest still confirms, so nothing is ordered by
// accident. Items come from the server and are always real, in-stock menu rows.
async function fetchSuggestions(){try{return await api('suggest',{cart});}catch{return null}}
function suggestionMarkup(s){
 if(!s?.items?.length)return '';
 return `<section class="suggest"><div class="suggest-head"><span class="ai-mark">\u2727</span><strong>${e(language==='ar'?s.reasonAr:s.reason)}</strong></div><div class="suggest-list">${s.items.map(m=>`<button type="button" class="suggest-item" data-do="suggest-add" data-id="${e(m.id)}"><span class="suggest-body"><strong>${e(nameOf(m))}</strong><small>${money(m.price)}</small></span><i aria-hidden="true">+</i></button>`).join('')}</div><p class="fine">${s.mode==='Live Gemini'?t('Suggested for your order'):t('Demo rules')}</p></section>`;
}
async function offerSuggestions(){const s=await fetchSuggestions();if(!s?.items?.length)return;modal('Anything else?',suggestionMarkup(s)+button('No thanks','dismiss','','secondary full'));}
async function fillCartSuggestions(){const host=$('#cart-suggest');if(!host)return;const s=await fetchSuggestions();if(host.isConnected)host.innerHTML=suggestionMarkup(s);}

// ---- Digital receipt -------------------------------------------------------
// A receipt is only ever rendered from a server-confirmed payment. For provider
// checkouts that means polling until the verified webhook has landed; clicking
// Pay is never treated as confirmation.
const AWAITING='resuto-awaiting-checkout';
const receiptScreen=html=>{screen='receipt';shell(`<main class="consumer-main receipt-screen">${html}</main>`);};
function receiptPage(r,opts={}){receipt=r;receiptScreen(receiptSuccess(r,{showRate:!visit?.rated&&r.kind!=='deposit',...opts}));}
const receiptRetry=message=>receiptScreen(receiptFailed(message)+`<div class="receipt-actions receipt-actions-primary">${button('Back to my bill','receipt-done','','primary full')}</div>`);

async function awaitCheckout(id,shareToken){
 receiptScreen(receiptSkeleton());
 const deadline=Date.now()+120000;
 while(Date.now()<deadline){
  let result;
  try{result=await api('receipt?checkout='+encodeURIComponent(id)+(shareToken?'&share='+encodeURIComponent(shareToken):''));}
  catch(err){sessionStorage.removeItem(AWAITING);return receiptRetry(err.message);}
  if(result.status==='paid'){sessionStorage.removeItem(AWAITING);if(shareToken)share=await api('share?token='+shareToken);else visit=await api('visit').catch(()=>visit);return receiptPage(result.receipt);}
  if(result.status==='failed'){sessionStorage.removeItem(AWAITING);return receiptRetry(t('The checkout expired before it was confirmed. No payment was taken.'));}
  await new Promise(done=>setTimeout(done,2000));
 }
 // Still unconfirmed: say so plainly rather than showing a paid receipt.
 receiptScreen(receiptSkeleton('Still confirming with your bank')+`<div class="receipt-actions receipt-actions-primary">${button('Back to my bill','receipt-done','','primary full')}</div>`);
}

// Runs on load so a refresh resumes confirmation instead of replaying a payment.
async function resumeCheckout(){
 const flag=new URLSearchParams(location.search).get('checkout'),awaiting=JSON.parse(sessionStorage.getItem(AWAITING)||'null');
 if(!flag&&!awaiting)return false;
 if(flag)history.replaceState(null,'',path);
 if(flag==='cancelled'){sessionStorage.removeItem(AWAITING);receiptRetry(t('Checkout was cancelled. No payment was taken.'));return true;}
 if(!awaiting)return false;
 await awaitCheckout(awaiting.id,awaiting.share);
 return true;
}

async function showReceipt(query,opts){
 const result=await api('receipt?'+query);
 if(result.status!=='paid'||!result.receipt)return receiptRetry(t('This payment has not been confirmed yet.'));
 receiptPage(result.receipt,opts);
}

// Receipts outlive their visit: a closed table still lists what was paid.
const receiptHistory=()=>{const source=(visit||closed)?.receipts||[];return !source.length?'':`<section class="receipt-history"><h2>${t('Receipts')}</h2><div class="receipt-list">${source.map(x=>`<button type="button" class="receipt-list-item" data-do="receipt-view" data-id="${e(x.paymentId)}"><span><strong>${t(x.share?'Your share':'Bill payment')}</strong><small>${new Intl.DateTimeFormat(language==='ar'?'ar-EG':'en-GB',{timeZone:'Africa/Cairo',day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}).format(x.at)}</small></span><b dir="ltr">${money(x.amount)}</b></button>`).join('')}</div></section>`;};
function closedVisitPage(){screen='closed';shell(`<main class="consumer-main status-page"><span class="overline">${t('Thank you for visiting')}</span><h1>${t('Your table is settled.')}</h1><div class="status-actions">${button('Browse menu','menu','','secondary')}</div>${receiptHistory()}</main>`);}

// A self-contained copy of the paper, for saving or printing.
async function downloadReceipt(){
 if(!receipt)return;
 const css=await fetch('/receipt.css').then(r=>r.text()).catch(()=>'');
 const html=`<!doctype html><html lang="${language}" dir="${language==='ar'?'rtl':'ltr'}"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${t('Receipt')} ${receipt.id}</title><style>body{margin:0;padding:28px 16px;background:#f2f4ef;display:flex;justify-content:center;font-family:Inter,system-ui,sans-serif}${css}</style></head><body>${receiptDocument(receipt)}</body></html>`;
 const url=URL.createObjectURL(new Blob([html],{type:'text/html'})),link=document.createElement('a');
 link.href=url;link.download=`receipt-${receipt.id}.html`;document.body.append(link);link.click();link.remove();
 setTimeout(()=>URL.revokeObjectURL(url),4000);
 toast('Receipt saved.');
}

function rating(){modal('How was your experience?',`<form data-guest-form="rating"><fieldset class="rating-stars"><legend>${t('Overall experience')}</legend>${[1,2,3,4,5].map(n=>`<label><input type="radio" name="overall" value="${n}" required aria-label="${n} / 5"><span>★</span></label>`).join('')}</fieldset><details><summary>${t('Add details (optional)')}</summary>${['food','service','speed','value'].map(k=>`<label>${t(k[0].toUpperCase()+k.slice(1))}<select name="${k}"><option value="">—</option>${[1,2,3,4,5].map(n=>`<option value="${n}">${n} ★</option>`).join('')}</select></label>`).join('')}<label>${t('What could we improve?')}<textarea name="comment" maxlength="1000"></textarea></label></details><button class="primary full">${t('Send rating')}</button>${button('Skip','dismiss','','secondary full')}</form>`);}
function cairoDate(value){let guess=Date.parse(value+'Z');for(let i=0;i<3;i++){const local=new Intl.DateTimeFormat('sv-SE',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(guess)).replace(' ','T');guess+=Date.parse(value+'Z')-Date.parse(local+'Z')}return guess;}
let reservationCriteria={date:new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Cairo'}).format(Date.now()+86400000),time:'21:00',party:4},listMode=false;
function reservationPage(){screen='reserve';shell(`<main class="consumer-main reservation-experience"><span class="overline">${t('Reservations')}</span><h1>${t('Choose your perfect spot.')}</h1><form data-guest-form="availability" class="reservation-filters"><label>${t('Branch')}<select name="branchId">${data.branches.filter(b=>b.reservations).map(b=>`<option value="${b.id}">${e(language==='ar'?b.nameAr||b.name:b.name)}</option>`).join('')}</select></label>${input('Date','date','date',reservationCriteria.date,'required')}${input('Time','time','time',reservationCriteria.time,'required')}${input('Guests','party','number',reservationCriteria.party,'min="1" max="20" required')}<button class="primary">${t('Show available tables')}</button></form><div class="reservation-toolbar"><div class="state-legend">${['Available','Selected','Unavailable'].map(k=>`<span><i class="${k.toLowerCase()}"></i>${t(k)}</span>`).join('')}</div>${button(listMode?'Map':'List','map-list','','secondary')}</div><div class="reservation-map-layout"><section class="reservation-canvas">${listMode?`<div class="table-list">${data.tables.filter(x=>x.capacity>=Number(reservationCriteria.party)).map(x=>button(x.label+' · '+x.capacity+' '+t('Seats')+' · '+t(x.zone),'reserve-table',`data-id="${x.id}" ${!x.available?'disabled':''}`,'table-list-button')).join('')}</div>`:`<div class="reservation-map-scroll">${savedFloorSvg(data.floor,data.tables.map(x=>({...x,state:x.available?'available':'reserved',disabled:!x.available||x.capacity<Number(reservationCriteria.party)})),selected)}</div><div class="map-controls">${button('Zoom out','map-out','','icon')}${button('Fit','map-fit','','icon')}${button('Zoom in','map-in','','icon')}</div>`}</section><aside id="table-choice">${tableChoice()}</aside></div></main>`);}
function tableChoice(){const x=data.tables.find(x=>x.id===selected);return x?`<div class="table-selection"><span class="overline">${t('Selected')}</span><h2>${e(x.label)}</h2><p>${t(x.zone)} · ${x.capacity} ${t('Guests')}</p><div class="table-features">${(x.features||[]).map(f=>`<span>✓ ${t(f)}</span>`).join('')}</div>${button('Review reservation','reserve-review','','primary full')}</div>`:`<div class="table-selection"><div class="selection-art">⌖</div><h2>${t('Choose your table')}</h2><p>${t('A place for every guest.')}</p></div>`;}
function reviewReservation(){const x=data.tables.find(x=>x.id===selected);modal('Review reservation',`<p>${e(x.label)} · ${t(x.zone)} · ${reservationCriteria.party} ${t('Guests')}</p><p>${e(reservationCriteria.date)} · ${e(reservationCriteria.time)}</p>${moneyRow('Reservation deposit',data.settings.deposit)}<form data-guest-form="reserve">${input('Name','name','text','','required maxlength="100"')}${input('Contact','contact','tel','','required maxlength="100"')}<button class="primary full">${t('Confirm reservation')}</button></form>`);}
let mapScale=1;
document.addEventListener('input',ev=>{if(ev.target.id==='dish-search'){search=ev.target.value;$('#dish-grid').innerHTML=cards();}if(ev.target.id==='ai-preferences'){const text=ev.target.value.replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c));const budget=text.match(/(?:budget|under|ميزانيتنا|ميزانية|حدود|معانا)\D{0,8}(\d+)/i),party=text.match(/(?:إحنا|احنا|نحن|for|we are)\s*(\d+)/i);if(budget)$('dialog [name="budget"]').value=budget[1];if(party)$('dialog [name="party"]').value=party[1];if(/not spicy|مش.*حار|غير حار/i.test(text))$('dialog [name="mild"]').checked=true;}});
document.addEventListener('change',ev=>{if(ev.target.name==='options')sheetTotal();if(ev.target.name==='provider')updateProvider();if(ev.target.name==='branchId'&&ev.target.closest('[data-guest-form="online"]'))updateCheckoutBranch();if(ev.target.name==='type'&&$('#delivery-details')){const delivery=ev.target.value==='delivery';$('#delivery-details').hidden=!delivery;$('[name="address"]').required=delivery;$('#checkout-total').innerHTML=moneyRow('Total',cartTotal()+(delivery?data.settings.deliveryFee:0));}});
document.addEventListener('click',async ev=>{const table=ev.target.closest('[data-action="select-table"]');if(table&&screen==='reserve'&&table.getAttribute('aria-disabled')!=='true'){selected=table.dataset.id;reservationPage();return;}const el=ev.target.closest('[data-do]');if(!el||el.disabled)return;const action=el.dataset.do;
try{if(action==='dismiss')return close();if(action==='product')return product(el.dataset.id);if(action==='category'){category=el.dataset.category;return menu();}if(action==='menu'){screen='menu';return menu();}if(action==='cart')return cartSheet();if(action.startsWith('cart-')){const n=Number(el.dataset.index),id=cart[n]?.id;
    if(action==='cart-remove')cart.splice(n,1);
    else{const m=data.menu.find(x=>x.id===cart[n].id);
     if(action==='cart-plus'&&cartQtyOf(cart[n].id)>=m.stock)return toast('No more portions available.');
     cart[n].qty+=action==='cart-plus'?1:-1;if(cart[n].qty<1)cart.splice(n,1);}
    saveCart();if(id)syncDish(id);close();return cartSheet();}if(action==='checkout')return checkout();if(action==='assistant')return assistant();if(action==='accept-ai'){for(const x of recommendation.lines){const m=data.menu.find(m=>m.id===x.id);cart.push({id:x.id,qty:x.qty,price:m.price,options:[]})}saveCart();close();menu();return toast('Review your cart before placing the order.');}if(action==='status')return isCounter()?counterTicket():statusPage();if(action==='bill'){visit=await api('visit');return billSheet();}if(action==='full-pay')return payForm();if(action==='share-open')return payForm(true);if(action==='rate')return rating();if(action==='split-create')return splitChooser();if(action==='split-method')return splitForm(el.dataset.method);if(action==='qr'){const shareToken=el.dataset.url.split('/').pop();return modal('Share QR',`<img class="share-qr" src="/api/share-qr?token=${encodeURIComponent(shareToken)}" alt="${t('Private payment link QR')}"><p class="fine">${t('Anyone with this link can pay this fixed share.')}</p>`);}if(action==='copy'){await navigator.clipboard.writeText(el.dataset.url);return toast('Link copied');}if(action==='share'){if(navigator.share)await navigator.share({title:t('Your share'),url:el.dataset.url});else modal('Share',`<input aria-label="${t('Share')}" readonly value="${e(el.dataset.url)}">${button('Copy link','copy',`data-url="${e(el.dataset.url)}"`,'secondary full')}<a class="primary button" href="https://wa.me/?text=${encodeURIComponent(el.dataset.url)}" target="_blank" rel="noopener">WhatsApp</a>`);return;}if(action==='waiter'){await api('request',{type:'waiter',key:key()});return toast('Your server has been notified.');}if(action==='map-list'){listMode=!listMode;return reservationPage();}if(action==='reserve-table'){selected=el.dataset.id;return reservationPage();}if(action==='reserve-review')return reviewReservation();if(action.startsWith('map-')){mapScale=action==='map-fit'?1:Math.max(1,Math.min(2.5,mapScale+(action==='map-in'?.25:-.25)));$('.reservation-map-scroll .saved-floor').style.width=mapScale*100+'%';return;}if(action==='deposit'){const b={token:reservation.token,key:pending('deposit',{token:reservation.token})};close();receiptScreen(receiptSkeleton('Processing your deposit…'));reservation=await api('deposit',b);await showReceipt('reservation='+encodeURIComponent(reservation.token),{primary:'Browse menu'});return;}if(action==='go-menu'){location.href='/menu';return;}
   if(action==='receipt-view'){receiptScreen(receiptSkeleton('Opening your receipt…'));return showReceipt('payment='+encodeURIComponent(el.dataset.id),{celebrate:false});}
   if(action==='share-receipt'){receiptScreen(receiptSkeleton('Opening your receipt…'));return showReceipt('share='+encodeURIComponent(path.split('/')[2]),{celebrate:false});}
   if(action==='sheet-plus'||action==='sheet-minus'){
    const out=$('#sheet-qty'),field=$('dialog [name="qty"]'),max=Number($('[data-do="sheet-plus"]')?.dataset.max||99);
    const next=Math.max(1,Math.min(max,Number(out.textContent)+(action==='sheet-plus'?1:-1)));
    out.textContent=next;field.value=next;sheetTotal();return}
   if(action==='quick-add'||action==='qty-plus'){addToCart(el.dataset.id,1);return}
   if(action==='qty-minus'){addToCart(el.dataset.id,-1);return}
   if(action==='suggest-add'){const m=data.menu.find(x=>x.id===el.dataset.id);if(!m)return;
    const line=cart.find(l=>l.id===m.id&&!l.options?.length);if(line)line.qty++;else cart.push({id:m.id,qty:1,price:m.price,options:[]});
    saveCart();close();toast('Added to your order. Confirm when you are ready.');menu();return cartSheet();}
   if(action==='counter-pay-now')return payForm();
   if(action==='counter-pay-cashier'){await api('request',{type:'bill',method:'cash',key:pending('counter-cash',{visit:visit.id})});
    visit=await api('visit');counterTicket();return toast('Take your number to the counter to pay.');}
   if(action==='receipt-download')return downloadReceipt();
   // Web Share where the device offers it; anything but a user cancel falls back to the clipboard.
   if(action==='receipt-share'){const text=receiptShareText(receipt),copy=async()=>{await navigator.clipboard.writeText(text);toast('Receipt copied.');};
    if(navigator.share){try{await navigator.share({title:t('Receipt')+' '+receipt.id,text});}catch(err){if(err.name!=='AbortError')await copy();}}else await copy();return;}
   if(action==='receipt-order'){visit=await api('visit');return statusPage();}
   if(action==='receipt-done'){receipt=null;if(share)return sharePage();if(reservation&&!visit){location.href='/menu';return;}
   try{const current=await api('visit');if(current.status==='open'){visit=current;closed=null;}else{visit=null;closed=current;}}catch{visit=null;}
   return visit?.orders.length?(isCounter()?counterTicket():statusPage()):closed?.receipts?.length?closedVisitPage():menu();}if(action==='dine-order'){if(busy)return;busy=true;el.disabled=true;const payload={lines:cart};await api('order',{...payload,key:pending('dine-order',payload)});sessionStorage.removeItem('pending-v2-dine-order');cart=[];saveCart();close();visit=await api('visit');if(isCounter())counterTicket();else statusPage();await offerSuggestions();return;}
}catch(err){toast(err.message);el.disabled=false;}finally{busy=false;}});
document.addEventListener('keydown',ev=>{if(screen==='reserve'&&['Enter',' '].includes(ev.key)&&ev.target.matches('[data-action="select-table"]')){ev.preventDefault();ev.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('submit',async ev=>{const form=ev.target;if(!form.dataset.guestForm)return;ev.preventDefault();if(busy)return;busy=true;const submit=form.querySelector('button:not([type])');if(submit)submit.disabled=true;const fd=new FormData(form),b=Object.fromEntries(fd),kind=form.dataset.guestForm;
try{if(kind==='add'){const m=data.menu.find(x=>x.id===form.dataset.id),options=fd.getAll('options'),qty=Number(b.qty),price=m.price+m.modifiers.filter(x=>options.includes(x.id)).reduce((n,x)=>n+x.price,0);const same=cart.find(l=>l.id===m.id&&JSON.stringify(l.options||[])===JSON.stringify(options));if(same)same.qty+=qty;else cart.push({id:m.id,qty,price,options});saveCart();close();syncDish(m.id);toast('Added to your order. Confirm when you are ready.');}
 if(kind==='online'){const payload={...b,lines:cart};const result=await api('online-order',{...payload,key:pending('online',payload)});token=result.token;sessionStorage.setItem('resuto-token',token);sessionStorage.removeItem('pending-v2-online');cart=[];saveCart();visit=await api('visit');close();statusPage();if(b.payment==='demo')rating();else payForm();}
 if(kind==='ai'){const thread=$('#ai-result');thread.insertAdjacentHTML('beforeend',`<div class="chat-bubble user"><p>${e(b.text||tr('Suggest a meal with my preferences','اقترح وجبة حسب تفضيلاتي'))}</p></div><p data-chat-loading role="status">${tr('Checking the menu…','أراجع القائمة…')}</p>`);thread.scrollTop=thread.scrollHeight;const r=await api('recommend',{...b,party:Number(b.party),budget:Math.round(Number(b.budget)*100),vegetarian:!!b.vegetarian,mild:!!b.mild,exclude:fd.getAll('exclude'),language,cart,branchId:data.branches[0].id});renderRecommendation(r);}
 if(kind==='split'){const method=b.method||'equal',payload={method,people:Number(b.people),names:String(b.names||'').split('\n')};if(method==='custom')payload.amounts=String(b.amounts||'').split(/\r?\n|,/).map(x=>Math.round(Number(x.trim())*100)).filter(Number.isFinite);if(method==='items'){payload.allocations=Array.from({length:Number(b.people)},()=>({items:[]}));for(const [name,value]of fd)if(name.startsWith('item:')){const [,orderId,lineIndex,unit]=name.split(':');const shareIndex=Number(value);if(payload.allocations[shareIndex])payload.allocations[shareIndex].items.push({orderId,lineIndex:Number(lineIndex),unit:Number(unit)});}}await api('split',{...payload,key:pending('split',payload)});visit=await api('visit');close();billSheet();}
 if(kind==='bill-payment'||kind==='share-payment'){const isShare=kind==='share-payment',payload={...b,amount:isShare?share.amount:visit.bill.due};if(['cash','instapay'].includes(b.provider)){await api('request',{type:'bill',method:b.provider,key:pending('payment-request',payload)});close();toast(b.provider==='cash'?'Payment request sent.':'InstaPay transfer awaits manager confirmation.');if(!isShare){visit=await api('visit');statusPage();}}else if(b.provider==='demo'){close();receiptScreen(receiptSkeleton('Processing your payment…'));
   if(isShare){share=await api('share-pay',{token:path.split('/')[2],name:b.firstName,key:pending('share-pay',payload)});await showReceipt('share='+encodeURIComponent(path.split('/')[2]));}
   else{const settled=await api('pay',{amount:payload.amount,key:pending('bill-payment',payload)});visit=await api('visit');await showReceipt('payment='+encodeURIComponent(settled.paymentId));}}else{if(b.provider==='paymob-wallet'){payload.provider='paymob';payload.method='wallet';}const result=await api('checkout',{...payload,...(isShare?{shareToken:path.split('/')[2]}:{}),key:pending('checkout',payload)});
    if(result.checkoutId)sessionStorage.setItem(AWAITING,JSON.stringify({id:result.checkoutId,share:isShare?path.split('/')[2]:null}));
    location.href=result.url;}}
 if(kind==='rating'){const payload={overall:Number(b.overall),comment:b.comment||'',...(share?{shareToken:path.split('/')[2]}:{})};for(const k of ['food','service','speed','value'])if(b[k])payload[k]=Number(b[k]);await api('rating',payload);close();toast('Thank you for your feedback.');}
 if(kind==='availability'){reservationCriteria={...b,party:Number(b.party)};data=await api('public?start='+cairoDate(b.date+'T'+b.time));selected=null;reservationPage();}
 if(kind==='reserve'){const payload={...b,tableId:selected,party:Number(reservationCriteria.party),start:cairoDate(reservationCriteria.date+'T'+reservationCriteria.time)};reservation=await api('reserve',{...payload,key:pending('reserve',payload)});close();modal('Reservation deposit',`${moneyRow('Reservation deposit',reservation.deposit)}<p>${t('Test mode. No real money is charged.')}</p>${button('Pay test deposit','deposit','','primary full')}`);}
}catch(err){$('#ai-result [data-chat-loading]')?.remove();toast(err.message);}finally{busy=false;if(submit)submit.disabled=false;}});
async function load(){data=await api('public');if(path.startsWith('/s/')){share=await api('share?token='+path.split('/')[2]);return await resumeCheckout()||sharePage();}if(path==='/restaurant')return home();if(path==='/reserve')return reservationPage();if(path.startsWith('/t/')){const joined=await api('table-session',{qr:path.split('/')[2]});token=joined.token;if(token)sessionStorage.setItem('resuto-token',token);else sessionStorage.removeItem('resuto-token');}if(token){try{const current=await api('visit');if(current.status==='open')visit=current;else{visit=null;closed=current;}}catch{visit=null;}}if(await resumeCheckout())return;if(visit?.type==='counter'&&visit.orders.length)return counterTicket();if(path==='/order'&&visit?.orders.length)return statusPage();if(path==='/order'&&closed?.receipts?.length)return closedVisitPage();return menu();}
$('#app').innerHTML=`<div class="loading-shell"><span class="brand-mark">r</span><p>${t('Loading…')}</p></div>`;
try{await load();}catch(err){shell(`<main class="invitation"><h1>${t('Something went wrong. Please try again.')}</h1><p>${e(err.message)}</p><a href="/menu">${t('Browse menu')}</a></main>`);}
setInterval(async()=>{if(document.hidden||busy||screen==='receipt')return;try{const event=await api('events');if(event.revision===revision)return;revision=event.revision;if(share){share=await api('share?token='+path.split('/')[2]);if(!$('dialog')&&!document.activeElement.matches('input,textarea,select'))sharePage();}else if(visit){visit=await api('visit');if($('#split-live')){$('#split-live').innerHTML=splitMarkup();$('#bill-summary').innerHTML=moneyRow('Total',visit.bill.total)+moneyRow('Reservation deposit',visit.bill.credit)+moneyRow('Paid',visit.bill.paid)+moneyRow('Remaining',visit.bill.due)+`<progress max="${visit.bill.total||1}" value="${Math.min(visit.bill.total,visit.bill.paid+visit.bill.credit)}" aria-label="${t('Payment progress')}"></progress>`;}if(!$('dialog')&&screen==='status')statusPage();else if(!$('dialog')&&screen==='counter')counterTicket();}else if(path.startsWith('/t/')&&!$('dialog')){await load();}}catch{}},2000);

document.addEventListener('click',ev=>{const b=ev.target.closest('[data-chat-prompt]');if(!b)return;const input=$('#ai-preferences');input.value=b.dataset.chatPrompt;input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();});
